const viva = require('./_viva');

const clean = (v, n) => String(v == null ? '' : v).replace(/[\u0000-\u001f<>]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);

module.exports = async (req, res) => {
  if (req.method !== 'POST') { res.setHeader('Allow', 'POST'); return res.status(405).json({ error: 'Use POST.' }); }
  if (!process.env.VIVA_CLIENT_ID || !process.env.VIVA_SOURCE_CODE || !process.env.ORDERS_ENDPOINT)
    return res.status(503).json({ error: 'The shop is not open yet.' });

  const body = viva.readBody(req);
  if (body.acceptedTerms !== true) return res.status(400).json({ error: 'Please accept the terms of sale first.' });

  // ---- items, priced on the server
  const lines = [];
  for (const it of (Array.isArray(body.items) ? body.items : []).slice(0, 30)) {
    const p = CATALOG.products.find(x => x.id === it.id);
    const qty = Math.max(1, Math.min(10, parseInt(it.qty, 10) || 0));
    if (!p || !it.qty) continue;
    lines.push({ id: p.id, name: p.name, qty, price: p.price });
  }
  if (!lines.length) return res.status(400).json({ error: 'Your cart is empty.' });
  const region = CATALOG.shipping.find(r => r.id === body.region);
  if (!region) return res.status(400).json({ error: 'Please choose a delivery option.' });

  // ---- customer and delivery address
  const c = body.customer || {};
  const cu = {
    name: clean(c.name, 80), email: clean(c.email, 120).toLowerCase(), phone: clean(c.phone, 30),
    address: clean(c.address, 160), city: clean(c.city, 60), postcode: clean(c.postcode, 12),
    country: clean(c.country, 2).toUpperCase(), notes: clean(c.notes, 500),
  };
  if (cu.name.length < 2) return res.status(400).json({ error: 'Please enter your full name.' });
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(cu.email)) return res.status(400).json({ error: 'Please enter a valid email address.' });
  if (cu.phone.replace(/\D/g, '').length < 7) return res.status(400).json({ error: 'Please enter a phone number for the courier.' });
  if (cu.address.length < 4 || cu.city.length < 2 || cu.postcode.length < 3) return res.status(400).json({ error: 'Please fill in the full delivery address.' });
  if (!region.countries.includes(cu.country)) return res.status(400).json({ error: 'That country is not covered by the delivery option you chose.' });

  const subtotal = lines.reduce((s, l) => s + l.price * l.qty, 0);
  const total = subtotal + region.amount;
  const ref = 'OGS-' + Date.now().toString(36).toUpperCase().slice(-6) + Math.random().toString(36).slice(2, 4).toUpperCase();
  const summary = lines.map(l => l.name + (l.qty > 1 ? ' ×' + l.qty : '')).join(', ');

  try {
    const orderCode = await viva.createOrder({
      amount: total,                                              // in cents
      customerTrns: clean('OGCODE order ' + ref + ': ' + summary + ' + delivery', 500),
      customer: { email: cu.email, fullName: cu.name, phone: cu.phone, countryCode: cu.country, requestLang: cu.country === 'GR' || cu.country === 'CY' ? 'el-GR' : 'en-GB' },
      merchantTrns: ref,
      sourceCode: process.env.VIVA_SOURCE_CODE,
      paymentTimeout: 1800,
      disableExactAmount: false,
      tags: ['website'],
    });
    await viva.sheet({
      type: 'order',
      order: { ref, orderCode, items: lines, subtotal, shipping: region.amount, total, delivery: region.label, customer: cu, env: viva.LIVE ? 'live' : 'demo' },
    });
    return res.status(200).json({ url: viva.checkoutUrl(orderCode), ref });
  } catch (e) {
    const msg = String(e && e.message || e);
    console.error('checkout', msg);
    // short reason code for troubleshooting (no keys or personal data)
    const stage = /login failed \((\d+)\)(.*)/.test(msg) ? 'viva-login-' + RegExp.$1 + RegExp.$2
      : /did not create the order \((\d+)\): (.{0,160})/.test(msg) ? 'viva-order-' + RegExp.$1 + ': ' + RegExp.$2
      : /sheet/i.test(msg) ? 'sheet: ' + msg.slice(0, 80) : 'other';
    return res.status(502).json({ error: 'Checkout could not be started.', stage });
  }
};
